<script lang="ts">
  import { onDestroy } from 'svelte';
  import {
    setCaptureModalShow,
    setCaptureModalClose,
    type CaptureModalData,
  } from '../bridge/captureModalBridge.js';
  import { game } from '../../gameManager.js';
  import { uiText } from '../ui/i18n.ts';
  import { useGameLanguageTick } from '../lib/useGameLanguageTick.svelte.ts';

  const { trackGameLanguage } = useGameLanguageTick();

  let visible = $state(false);
  let data = $state<CaptureModalData | null>(null);

  let levelPrefix = $derived.by(() => {
    trackGameLanguage();
    return uiText('state.levelShort', 'Lvl', {}, game);
  });

  function show(payload: CaptureModalData) {
    data = payload;
    visible = true;
    const modal = document.getElementById('captureModal');
    if (!modal) return;
    if (payload.sceneStyles) {
      for (const [key, value] of Object.entries(payload.sceneStyles)) {
        modal.style.setProperty(key, value);
      }
    }
    modal.classList.add('show');
  }

  function close() {
    visible = false;
    data = null;
    document.getElementById('captureModal')?.classList.remove('show');
  }

  setCaptureModalShow(show);
  setCaptureModalClose(close);
  onDestroy(() => {
    setCaptureModalShow(() => {});
    setCaptureModalClose(() => {});
  });
</script>

{#if visible && data}
  <div class="capture-layout" data-action="stopPropagation" data-action-stop>
    <div class="capture-target-card rarity-{data.enemyRarity}">
      <div class="capture-scene">
        <img src={data.spriteUrl} class="capture-sprite" alt={data.enemyName} />
      </div>
      <div class="capture-target-name">{data.enemyName}</div>
      <span class="rarity-label capture-target-rarity {data.enemyRarity}">{data.enemyRarity}</span>
      <div class="capture-target-level">{levelPrefix} {data.enemyLevel}</div>
    </div>
    <div class="balls-grid">
      {#each data.balls as ball (ball.type)}
        <button
          type="button"
          class="ball-select-btn"
          data-action="tryCapture"
          data-arg={ball.type}
          disabled={ball.disabled}
        >
          <div class="ball-count-badge">x{ball.count}</div>
          {#if ball.img}
            <img src={ball.img} class="ball-icon-img" alt={ball.name} />
          {:else}
            <div class="ball-icon-large">{ball.icon}</div>
          {/if}
          <div class="capture-ball-name">{ball.name}</div>
          <div class="capture-ball-rate">{ball.visualRate.toFixed(0)}%</div>
          <div class="capture-chance-bar">
            <div
              class="capture-chance-fill"
              style="width:{ball.visualRate}%; --capture-bar-color:{ball.barColor};"
            ></div>
          </div>
        </button>
      {/each}
    </div>
  </div>
  <button type="button" class="btn capture-flee-btn" data-action="skipCapture">
    <span id="captureSkipLabel">{data.skipLabel}</span>
  </button>
{/if}
